#include <bits/stdc++.h>
using namespace std;

int n, m, maxMask;
vector<vector<vector<int>>> dp;
vector<int> popCount;

int countSetBits(int num) {
    int count = 0;
    while (num != 0) {
        count++;
        num &= (num - 1);
    }
    return count;
}

bool checkPattern(int a, int b, int c) {
    int combined = (maxMask - 1) & (b | (b << 1) | (b >> 1) | a | c);
    return combined == maxMask - 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    if (n < m) {
        int tmp = n; n = m; m = tmp;
    }
    maxMask = 1 << m;
    dp.assign(n + 1, vector<vector<int>>(maxMask, vector<int>(maxMask, 100)));
    popCount.assign(maxMask, 0);

    for (int i = 0; i < maxMask; i++) {
        popCount[i] = countSetBits(i);
        dp[0][0][i] = 0;
    }

    for (int rowIdx = 1; rowIdx <= n; rowIdx++) {
        for (int prevMask = 0; prevMask < maxMask; prevMask++) {
            for (int currMask = 0; currMask < maxMask; currMask++) {
                for (int nextMask = 0; nextMask < maxMask; nextMask++) {
                    if (dp[rowIdx - 1][prevMask][nextMask] != 100 && checkPattern(prevMask, nextMask, currMask)) {
                        dp[rowIdx][currMask][nextMask] = std::min(dp[rowIdx][currMask][nextMask], dp[rowIdx - 1][prevMask][nextMask] + popCount[nextMask]);
                    }
                }
            }
        }
    }

    int minRes = INT_MAX;
    for (int i = 0; i < maxMask; i++) {
        minRes = std::min(dp[n][i][0], minRes);
    }
    cout << n * m - minRes << "\n";
    return 0;
}
